export const RUNNER_SYNC_RECEIPT_SCHEMA_ID = 'atm.runnerSyncPublicationReceipt.v1';
export function createRunnerSyncReceipt(input) { const ticketId = String(input?.ticketId ?? '').trim(); const sourceDigest = String(input?.sourceDigest ?? '').trim(); const runnerDigest = String(input?.runnerDigest ?? '').trim(); return { schemaId: RUNNER_SYNC_RECEIPT_SCHEMA_ID, ticketId, sourceDigest, runnerDigest, published: input?.published === true, durableTicketIdentity: Boolean(ticketId && sourceDigest && runnerDigest), stdoutOnlyRejected: true, rollbackCommand: `node atm.mjs broker runner-sync status --ticket ${ticketId} --json` }; }
